    },
  },
});

type RuntimeEnv = Record<string, string> | undefined;

// Add TypeScript declaration for window._env_
declare global {
  interface Window {
    _env_?: RuntimeEnv;
  }
}

/**
 * Resolves the port used to download env-config.js.
 * Priority:
 *   1. Explicit port in the current URL (window.location.port)
 *   2. Runtime / build-time variable REACT_APP_PROXY_PORT
 *   3. Protocol default (https → 443, http → 80) or dev fallback (3001)
 */
const resolveEnvConfigPort = (): string | undefined => {
  const currentPort = window.location.port;

  if (currentPort && currentPort !== '3000') return currentPort;

  const buildTimePort = process.env.REACT_APP_PROXY_PORT;
  if (buildTimePort) return buildTimePort;

  // For development environment
  if (currentPort === '3000') return '3001';

  // For HTTPS with empty port string or HTTP without port
  if (currentPort === '') {
    return window.location.protocol === 'https:' ? '443' : '80';
  }

  // Fallback for any other case
  return '3001';
};

/**
 * Fetches env-config.js and injects the variables into window._env_.
 */
const fetchEnvConfig = async (): Promise<void> => {
  try {
    // Check if window._env_ is already defined (from the injected script)
    if (window._env_) {
      console.log('Environment variables already loaded from injected script');
      return;
    }

    const { protocol, hostname } = window.location;
    const port = resolveEnvConfigPort();

    // Do not include default ports (80/443) in the URL
    const omitPort =
        (protocol === 'https:' && port === '443') ||
        (protocol === 'http:' && port === '80');
    const portSegment = omitPort || !port ? '' : `:${port}`;

    const envConfigUrl = `${protocol}//${hostname}${portSegment}/env-config.js`;

    const response = await fetch(envConfigUrl);
    if (!response.ok) {
      console.error(
          `Failed to load env-config.js (status ${response.status})`
      );
      return;
    }

    // For JavaScript response, we need to evaluate it instead of parsing as JSON
    // The script will set window._env_ directly, so we don't need to assign it here
    const scriptText = await response.text();

    // Create a function from the script text and execute it in the current context
    // This is safer than using eval() directly
    new Function(scriptText)();

    console.log('Environment variables loaded dynamically');
  } catch (err) {
    console.error('Error while loading environment variables:', err);
  }
};

// Load environment variables before rendering the app
fetchEnvConfig().then(() => {
  const root = ReactDOM.createRoot(
      document.getElementById('root') as HTMLElement
  );

  root.render(
      <React.StrictMode>
        <BrowserRouter future={{ v7_startTransition: true, v7_relativeSplatPath: true }}>
          <ThemeProvider theme={theme}>
            <CssBaseline />
            <App />
          </ThemeProvider>
        </BrowserRouter>
      </React.StrictMode>
  );
});

// User management and authentication for Nauthilus UI
// This module provides user management and authentication independently of the Nauthilus service

import { jwtDecode } from 'jwt-decode';
import * as bcrypt from 'bcryptjs';
import Cookies from 'js-cookie';
import axios from './axiosConfig';

// Helper to set auth cookies from server response in a DRY manner
const setCookiesFromResponse = (
  data: any,
  defaultTokenSeconds: number = 3600,
  defaultRefreshSeconds: number = 86400
): { token: string; refreshToken: string } | null => {
  if (!data || !data.token) {
    return null;
  }

  const token: string = data.token;
  const refreshToken: string = data.refreshToken || token;

  const tokenExpiry: Date = data.expiresAt
    ? new Date(data.expiresAt * 1000)
    : new Date(Date.now() + defaultTokenSeconds * 1000);

  Cookies.set(TOKEN_COOKIE_NAME, token, {
    ...COOKIE_OPTIONS,
    expires: tokenExpiry,
  });

  Cookies.set(REFRESH_TOKEN_COOKIE_NAME, refreshToken, {
    ...COOKIE_OPTIONS,
    expires: new Date(Date.now() + defaultRefreshSeconds * 1000),
  });

  return { token, refreshToken };
};

// Helper to update user's lastLogin while preserving lastModified
const updateUserLastLogin = async (username: string): Promise<void> => {
  const now = new Date().toISOString();
  try {
    const users = await getUsers();
    const currentUser = users.find(u => u.username === username);

    if (currentUser) {
      await updateUserProfile(username, {
        lastLogin: now,
        lastModified: currentUser.lastModified,
      });
    } else {
      await updateUserProfile(username, {
        lastLogin: now,
      });
    }
    console.log('LastLogin timestamp updated successfully');
  } catch (updateError) {
    console.error('Failed to update lastLogin timestamp:', updateError);
  }
};

// Helper to store credentials for token refresh (sessionStorage)
const storeCredentialsForTokenRefresh = (username: string, password: string): void => {
  try {
    sessionStorage.setItem('auth_credentials', JSON.stringify({ username, password }));
    console.log('Stored credentials for token refresh');
  } catch (storageError) {
    console.error('Failed to store credentials for token refresh:', storageError);
  }
};

// Cookie names for token storage
const TOKEN_COOKIE_NAME = 'nauthilus_token';
const REFRESH_TOKEN_COOKIE_NAME = 'nauthilus_refresh_token';

// Cookie options
const COOKIE_OPTIONS = {
  secure: window.location.protocol === 'https:',
  sameSite: 'strict' as const,
  path: '/'
};

